# -*- coding: utf-8 -*-
"""Болячки моделей: какие коды типичны для конкретных двигателей/коробок и что за ними обычно стоит.

brands — подстроки марки из VinDecoder (без учёта регистра); models — подстроки модели из VinDecoder (пусто = вся марка);
years — включительно; vin — префиксы VIN для особых случаев (Chevrolet Niva X9L).
title — короткий заголовок, note — объяснение с цепочкой и что делать, mileage — когда обычно.
Только широко известные по drive2/drom проблемы; ссылки не выдумываем — их подтянет поиск нейронки.
"""

ISSUES = []


def issue(brands, codes, title, note, models=(), years=None, mileage="", vin=(), severity=None, price=0):
    ISSUES.append(dict(brands=list(brands), models=list(models), years=list(years) if years else None, vin=list(vin),
                       codes=list(codes), title=title, note=note.strip(), mileage=mileage, severity=severity, price=price))


